    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To determine the pooled prevalence of SSI following cesarean section and its predictors in Ethiopia.",
      "reason": "The manuscript provides an explicit objective statement describing the review's aims (pooled prevalence and predictors). However, the objective is not presented using a formal question-formulation framework (e.g., PICO or an equivalent), so it only partially meets the requirement."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "This SRMA included all articles conducted in all regional state of Ethiopia reporting the prevalence/proportion/incidence of SSI after cesarean section and/or associated factors. All observational study designs were included in this SRMA.",
      "reason": "The conditional item applies to reviews of intervention effects. This review is a prevalence and predictors SRMA of observational studies (not intervention effects), so specification of planned comparisons using PICO is not applicable."
    }
  ],
  "confidence": 90
}

{
