    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "This SRMA included all articles conducted in all regional state of Ethiopia reporting the prevalence/proportion/incidence of SSI after cesarean section and/or associated factors. All observational study designs (case-control and cross-sectional study designs) were included in this SRMA.",
      "reason": "The manuscript specifies eligible settings (all regional states of Ethiopia) and eligible study designs (observational: case-control and cross-sectional) and the outcomes of interest (prevalence/incidence and associated factors). It does not specify follow-up requirements or other question-framework components (e.g., participant characteristics, timing/follow-up), so the eligibility characteristics are incompletely reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Both published articles and grey literatures published in English language from January 1 2013 to September 2023.",
      "reason": "The review states report characteristics: inclusion of published and grey literature, restriction to English language, and the dissemination years (January 1, 2013 to September 2023)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript states that \"Articles which lack our outcome of interest... were excluded,\" but does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_16",
      "quote": "Based on the study region, subgroup analyses were done.",
      "reason": "The review specifies one way studies were grouped for synthesis (subgroup analyses by study region). However, it does not comprehensively specify all groups used for each synthesis or explicitly link these groups to the comparisons defined in the review objectives, so reporting is partial."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided in the retrieved text for notable restrictions on eligibility (for example, the reason for the 2013–2023 date range or English-language restriction is not given)."
    }
